void usbnet_cdc_status ( struct usbnet * dev , struct urb * urb ) { struct usb_cdc_notification * event ; if ( urb -> actual_length < sizeof ( * event ) ) { return ; } if ( test_and_clear_bit ( EVENT_STS_SPLIT , & dev -> flags ) ) { dumpspeed ( dev , ( __le32 * ) urb -> transfer_buffer ) ; return ; } event = urb -> transfer_buffer ; switch ( event -> bNotificationType ) { case USB_CDC_NOTIFY_NETWORK_CONNECTION : netif_dbg ( dev , timer , dev -> net , "CDC: carrier %s\n" , event -> wValue ?"on" : "off" ) ; break ; case USB_CDC_NOTIFY_SPEED_CHANGE : netif_dbg ( dev , timer , dev -> net , "CDC: speed change (len %d)\n" , urb -> actual_length ) ; if ( urb -> actual_length != ( sizeof ( * event ) + 8 ) ) { set_bit ( EVENT_STS_SPLIT , & dev -> flags ) ; } else { dumpspeed ( dev , ( __le32 * ) & event [ 1 ] ) ; } break ; default : netdev_err ( dev -> net , "CDC: unexpected notification %02x!\n" , event -> bNotificationType ) ; break ; } } 